class StreamChecker {
    struct TrieNode {
        bool is_word = false;
        unordered_map<char, TrieNode*> next;
    };
    TrieNode* root;
    deque<char> stream;
    int max_len = 0;
public:
    StreamChecker(vector<string>& words) {
        root = new TrieNode();
        for (const string& w : words) {
            max_len = max(max_len, (int)w.size());
            TrieNode* curr = root;
            for (int i = (int)w.size() - 1; i >= 0; --i) {
                if (!curr->next.count(w[i])) curr->next[w[i]] = new TrieNode();
                curr = curr->next[w[i]];
            }
            curr->is_word = true;
        }
    }
    bool query(char letter) {
        stream.push_front(letter);
        if ((int)stream.size() > max_len) stream.pop_back();
        TrieNode* curr = root;
        for (char ch : stream) {
            if (curr->is_word) return true;
            if (!curr->next.count(ch)) return false;
            curr = curr->next[ch];
        }
        return curr->is_word;
    }
};

class StreamChecker {
    static class TrieNode {
        boolean isWord = false;
        TrieNode[] children = new TrieNode[26];
    }
    private final TrieNode root = new TrieNode();
    private final StringBuilder stream = new StringBuilder();
    private int maxLen = 0;

    public StreamChecker(String[] words) {
        for (String w : words) {
            maxLen = Math.max(maxLen, w.length());
            TrieNode node = root;
            for (int i = w.length() - 1; i >= 0; i--) {
                int idx = w.charAt(i) - 'a';
                if (node.children[idx] == null) node.children[idx] = new TrieNode();
                node = node.children[idx];
            }
            node.isWord = true;
        }
    }

    public boolean query(char letter) {
        stream.append(letter);
        if (stream.length() > maxLen) stream.deleteCharAt(0);
        TrieNode node = root;
        for (int i = stream.length() - 1; i >= 0; i--) {
            int idx = stream.charAt(i) - 'a';
            if (node.children[idx] == null) return false;
            node = node.children[idx];
            if (node.isWord) return true;
        }
        return false;
    }
}

class StreamChecker {
    constructor(words) {
        this.trie = {};
        this.stream = [];
        this.maxLen = 0;
        for (const w of words) {
            this.maxLen = Math.max(this.maxLen, w.length);
            let node = this.trie;
            for (let i = w.length - 1; i >= 0; i--) {
                const ch = w[i];
                if (!node[ch]) node[ch] = {};
                node = node[ch];
            }
            node['$'] = true;
        }
    }
    query(letter) {
        this.stream.unshift(letter);
        if (this.stream.length > this.maxLen) this.stream.pop();
        let node = this.trie;
        for (const ch of this.stream) {
            if (node['$']) return true;
            if (!node[ch]) return false;
            node = node[ch];
        }
        return Boolean(node['$']);
    }
}
